package com.specdriven.regression.runner;
import static org.assertj.core.api.Assertions.assertThat;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.specdriven.regression.cli.RegressionCommand;
import com.specdriven.regression.discovery.ReleasePackageService;
import com.specdriven.regression.productrepo.ProductRepoService;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class BoundedEvidenceCollectorTest {
 static final ObjectMapper JSON=new ObjectMapper();@TempDir Path temp;Path source,spec,out;ObjectNode manifest;ArrayNode files;
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 @BeforeEach void setup()throws Exception{source=Files.createDirectory(temp.resolve("source"));spec=temp.resolve("collection.json");out=temp.resolve("saved");manifest=JSON.createObjectNode();manifest.put("schema_version","runner-collection.v1");manifest.put("run_id","public-run");manifest.put("correlation_id","public-correlation");manifest.put("payload_profile","standard");manifest.put("deadline_ms",30000);manifest.putNull("canonical_result");var versions=manifest.putObject("artifact_versions");for(String k:List.of("runner","framework","provider","source","bundle","sut"))versions.put(k,"public-fixture-1");files=manifest.putArray("files");}
 void add(String path,String role,String text,boolean required)throws Exception{Path p=source.resolve(path);Files.createDirectories(p.getParent());Files.writeString(p,text);var f=files.addObject();f.put("path",path);f.put("role",role);f.put("bytes",Files.size(p));f.put("sha256",sha(Files.readAllBytes(p)));f.put("required",required);}
 record Result(int code,String stdout,String stderr,JsonNode receipt){}
 Result collect()throws Exception{Files.write(spec,JSON.writeValueAsBytes(manifest));var stdout=new ByteArrayOutputStream();var stderr=new ByteArrayOutputStream();int code=new RegressionCommand(new ProductRepoService(),new ReleasePackageService()).execute(new String[]{"runner-import","--collection-spec",spec.toString(),"--expected-spec-sha256",sha(Files.readAllBytes(spec)),"--source",source.toString(),"--out",out.toString()},new PrintStream(stdout),new PrintStream(stderr));Path receipt=out.resolve("collection.json");return new Result(code,stdout.toString(),stderr.toString(),Files.exists(receipt)?JSON.readTree(receipt.toFile()):JSON.createObjectNode());}
 @Test void finiteClosureSavedWithHashesAndNoProductVerdictInferred()throws Exception{add("canonical/evidence.json","evidence","{\"public\":true}\n",true);var r=collect();assertThat(r.code()).as(r.stdout()+r.stderr()).isZero();assertThat(r.receipt().path("collection").asText()).isEqualTo("COMPLETE");assertThat(r.receipt().path("publication").asText()).isEqualTo("SAVED");assertThat(r.receipt().path("framework_verdict").asText()).isEqualTo("UNKNOWN");assertThat(Files.readAllBytes(out.resolve("canonical/evidence.json"))).isEqualTo(Files.readAllBytes(source.resolve("canonical/evidence.json")));assertThat(Files.exists(out.resolve("aliases.json"))).isTrue();}
 @Test void auxiliaryLogsAreDerivedMaskedArtifactsWithOriginalIdentity()throws Exception{add("logs/run.stdout.log","log","Authorization: Bearer public-canary-secret\n",true);var r=collect();assertThat(r.code()).as(r.stdout()+r.stderr()).isZero();String saved=Files.readString(out.resolve("logs/run.stdout.log"));assertThat(saved).doesNotContain("public-canary-secret");assertThat(r.receipt().path("files").get(0).path("original_sha256").asText()).isNotEqualTo(r.receipt().path("files").get(0).path("saved_sha256").asText());}
 @Test void canonicalSecretNeverRewrittenOrPublished()throws Exception{add("canonical/result.json","canonical","{\"password\":\"public-canary-secret\"}",true);manifest.put("canonical_result","canonical/result.json");var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.receipt().path("collection").asText()).isEqualTo("INVALID");assertThat(Files.exists(out.resolve("canonical/result.json"))).isFalse();assertThat(Files.readString(source.resolve("canonical/result.json"))).contains("public-canary-secret");}
 @Test void missingRequiredAndOptionalHaveExplicitStates()throws Exception{add("canonical/evidence.json","evidence","{}",true);Files.delete(source.resolve("canonical/evidence.json"));var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.receipt().path("collection").asText()).isEqualTo("PARTIAL");assertThat(r.receipt().path("framework_verdict").asText()).isEqualTo("UNKNOWN");}
 @Test void invalidDeadlineCannotLaunchOrPublishSuccess()throws Exception{add("logs/run.stdout.log","log","public",true);manifest.put("deadline_ms",0);var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.stdout()).contains("BLOCKED");assertThat(Files.exists(out.resolve("SAVE.complete"))).isFalse();}
 @Test void declaredOversizeRefusedBeforePayloadRead()throws Exception{add("canonical/evidence.json","evidence","public",true);((ObjectNode)files.get(0)).put("bytes",4194305);var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.receipt().path("collection").asText()).isEqualTo("INVALID");assertThat(Files.exists(out.resolve("canonical/evidence.json"))).isFalse();}
 @Test void traversalNeverReadsOutsideAllowedSource()throws Exception{add("canonical/evidence.json","evidence","{}",true);((ObjectNode)files.get(0)).put("path","../outside.json");Files.writeString(temp.resolve("outside.json"),"private-outside-not-admitted");var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.stdout()+r.stderr()).doesNotContain("private-outside-not-admitted");assertThat(Files.exists(out.resolve("SAVE.complete"))).isFalse();}
 @Test void symlinkFinalAndParentAndHardlinkRejected()throws Exception{add("canonical/evidence.json","evidence","{}",true);Path f=source.resolve("canonical/evidence.json"),other=temp.resolve("other");Files.move(f,other);Files.createSymbolicLink(f,other);var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.receipt().path("collection").asText()).isEqualTo("INVALID");}
 @Test void tamperedFileCannotBorrowManifestHash()throws Exception{add("canonical/evidence.json","evidence","{}",true);Files.writeString(source.resolve("canonical/evidence.json"),"changed");var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.receipt().path("collection").asText()).isEqualTo("INVALID");}
 @Test void identityMismatchCannotBecomeFrameworkPass()throws Exception{add("canonical/result.json","canonical","{\"run_id\":\"wrong-run\",\"status\":\"passed\"}",true);manifest.put("canonical_result","canonical/result.json");var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.receipt().path("framework_verdict").asText()).isEqualTo("UNKNOWN");}
 @Test void preexistingOutputCannotBeOverwritten()throws Exception{add("logs/run.stdout.log","log","public",true);Files.createDirectory(out);Files.writeString(out.resolve("owner"),"retained");var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(Files.readString(out.resolve("owner"))).isEqualTo("retained");}
 @Test void producerAbsoluteReportsRemainVerbatimWithoutAbsoluteAliasCreation()throws Exception{String old="{\"result_ref\":\"/producer/private/location/result.json\"}";add("producer/framework-report.json","report",old,true);var r=collect();assertThat(r.code()).as(r.stdout()+r.stderr()).isZero();assertThat(Files.readString(out.resolve("producer/framework-report.json"))).isEqualTo(old);assertThat(r.receipt().path("producer_link_revalidation").asText()).isEqualTo("BLOCKED_ABSOLUTE_REFERENCE");}
 @Test void privateKeyBodyNeverSurvivesLogMasking()throws Exception{
  String key="public prefix\n-----BEGIN PRIVATE KEY-----\nPUBLIC_PRIVATE_KEY_BODY_CANARY\n-----END PRIVATE KEY-----\n";add("logs/private.stdout.log","log",key,true);var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.receipt().path("collection").asText()).isEqualTo("INVALID");assertThat(Files.exists(out.resolve("logs/private.stdout.log"))).isFalse();assertThat(Files.exists(out.resolve("SAVE.complete"))).isFalse();try(var paths=Files.walk(out)){for(Path f:paths.filter(Files::isRegularFile).toList())assertThat(Files.readString(f)).doesNotContain("PUBLIC_PRIVATE_KEY_BODY_CANARY");}assertThat(Files.readString(source.resolve("logs/private.stdout.log"))).isEqualTo(key);
 }
 @Test void truncatedPrivateKeyLogCannotYieldCompleteSave()throws Exception{add("logs/truncated.log","log","-----BEGIN OPENSSH PRIVATE KEY-----\nPUBLIC_UNCLOSED_KEY_BODY",true);var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(Files.exists(out.resolve("logs/truncated.log"))).isFalse();assertThat(Files.exists(out.resolve("SAVE.complete"))).isFalse();}
 void existingCanonicalFixture(boolean fail)throws Exception{
  Path fixture=Path.of("samples/40-evidence-reporting/evidence_hardening");
  add("canonical/result.json","canonical",Files.readString(fixture.resolve("valid_result.json")),true);manifest.put("canonical_result","canonical/result.json");manifest.put("run_id","RUN-EVIDENCE-001");((ObjectNode)manifest.path("artifact_versions")).put("framework","0.3.0");
  try(var paths=Files.list(fixture.resolve("evidence"))){for(Path p:paths.toList())add("canonical/evidence/"+p.getFileName(),p.getFileName().toString().equals("evidence_index.yaml")?"index":"evidence",Files.readString(p),true);}
  if(fail){Path file=source.resolve("canonical/result.json");ObjectNode d=(ObjectNode)JSON.readTree(file.toFile());d.put("status","failed");((ObjectNode)d.path("test_results").get(0)).put("status","failed");var f=d.putObject("failure");f.put("code","ASSERTION_FAILED");f.put("classification","ASSERTION_FAILED");f.put("reason","public synthetic producer failure");f.put("owner_action","review public fixture");Files.write(file,JSON.writeValueAsBytes(d));((ObjectNode)files.get(0)).put("bytes",Files.size(file));((ObjectNode)files.get(0)).put("sha256",sha(Files.readAllBytes(file)));}
 }
 @Test void relativeCanonicalGraphProducesSeparateControllerCoverageWithoutChangingProducer()throws Exception{
  existingCanonicalFixture(false);byte[] original=Files.readAllBytes(source.resolve("canonical/result.json"));var r=collect();assertThat(r.code()).as(r.stdout()+r.stderr()+r.receipt()).isZero();assertThat(r.receipt().path("validation").asText()).isEqualTo("VALID");assertThat(r.receipt().path("framework_verdict").asText()).isEqualTo("passed");assertThat(Files.exists(out.resolve("controller-derived/coverage/coverage.json"))).isTrue();assertThat(Files.readAllBytes(out.resolve("canonical/result.json"))).isEqualTo(original);
 }
 @Test void validProducerFailureRetainsFailedVerdictWithSavedCoverage()throws Exception{existingCanonicalFixture(true);var r=collect();assertThat(r.code()).as(r.stdout()+r.stderr()+r.receipt()).isZero();assertThat(r.receipt().path("framework_verdict").asText()).isEqualTo("failed");assertThat(Files.exists(out.resolve("controller-derived/coverage/coverage.md"))).isTrue();}
 @Test void unlistedCanonicalReferenceCannotExpandCollectorAllowlist()throws Exception{add("canonical/result.json","canonical","{\"run_id\":\"public-run\",\"evidence_refs\":[\"missing.json\"]}",true);manifest.put("canonical_result","canonical/result.json");var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.receipt().path("collection").asText()).isEqualTo("PARTIAL");}
 @Test void parserFailureAndRejectedTraversalNeverEchoRawCanaryDiagnostics()throws Exception{
  add("canonical/result.json","canonical","{PUBLIC_PARSER_CANARY",true);manifest.put("canonical_result","canonical/result.json");var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.stdout()+r.stderr()+r.receipt()).doesNotContain("PUBLIC_PARSER_CANARY");
 }
 @Test void rejectedAbsolutePathIsIdentifiedOnlyByDigest()throws Exception{
  add("canonical/evidence.json","evidence","{}",true);((ObjectNode)files.get(0)).put("path","/PUBLIC_PATH_CANARY/outside");var r=collect();assertThat(r.code()).isEqualTo(1);assertThat(r.stdout()+r.stderr()+r.receipt()).doesNotContain("PUBLIC_PATH_CANARY");assertThat(r.receipt().path("gaps").get(0).path("declared_ref_sha256").asText()).hasSize(64);
 }
}
